using Servicio.RetazoMarket.Business.DTOs.MovimientoProducto;
namespace Servicio.RetazoMarket.Business.Validators;
public static class MovimientoProductoValidator { private static readonly HashSet<string> Tipos=["ING","EGR","AJP","AJN"];public static IReadOnlyCollection<string> ValidarCreacion(CrearMovimientoProductoRequest r){var e=new List<string>();if(r is null)return ["La solicitud no puede ser nula."];if(r.id_producto<=0)e.Add("El producto es obligatorio.");var t=r.tipo_movimiento?.Trim().ToUpperInvariant();if(t is null||!Tipos.Contains(t))e.Add("El tipo debe ser ING, EGR, AJP o AJN.");if(r.cantidad<=0)e.Add("La cantidad debe ser mayor que cero.");if(string.IsNullOrWhiteSpace(r.motivo_mov))e.Add("El motivo es obligatorio.");else if(r.motivo_mov.Trim().Length>100)e.Add("El motivo no puede exceder 100 caracteres.");return e;}public static IReadOnlyCollection<string> ValidarFiltro(MovimientoProductoFiltroRequest r){var e=new List<string>();if(r is null)return ["El filtro no puede ser nulo."];if(!string.IsNullOrWhiteSpace(r.tipo_movimiento)&&!Tipos.Contains(r.tipo_movimiento.Trim().ToUpperInvariant()))e.Add("El tipo debe ser ING, EGR, AJP o AJN.");if(r.fecha_desde_utc>r.fecha_hasta_utc)e.Add("La fecha desde no puede ser posterior a la fecha hasta.");if(r.page_number<=0)e.Add("El número de página debe ser mayor que cero.");if(r.page_size<=0||r.page_size>100)e.Add("El tamaño de página debe estar entre 1 y 100.");return e;}public static int CalcularStock(int actual,string tipo,int cantidad)=>tipo is "ING" or "AJP"?checked(actual+cantidad):actual-cantidad;}
